void UntrustedUIHandlerAsyncWaiter::SearchForTabs(
    const std::string& query, std::optional<std::vector<::ai_chat::mojom::TabDataPtr>>* out_tabs) {
  base::RunLoop loop;
  proxy_->SearchForTabs(
      std::move(query),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::optional<std::vector<::ai_chat::mojom::TabDataPtr>>* out_tabs
,
             std::optional<std::vector<::ai_chat::mojom::TabDataPtr>> tabs) {*out_tabs = std::move(tabs);
            loop->Quit();
          },
          &loop,
          out_tabs));
  loop.Run();
}

std::optional<std::vector<::ai_chat::mojom::TabDataPtr>> UntrustedUIHandlerAsyncWaiter::SearchForTabs(
    const std::string& query) {
  std::optional<std::vector<::ai_chat::mojom::TabDataPtr>> async_wait_result;
  SearchForTabs(std::move(query),&async_wait_result);
  return async_wait_result;
}

void UntrustedUIHandlerAsyncWaiter::HasMemory(
    const std::string& memory, bool* out_exists) {
  base::RunLoop loop;
  proxy_->HasMemory(
      std::move(memory),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_exists
,
             bool exists) {*out_exists = std::move(exists);
            loop->Quit();
          },
          &loop,
          out_exists));
  loop.Run();
}

bool UntrustedUIHandlerAsyncWaiter::HasMemory(
    const std::string& memory) {
  bool async_wait_result;
  HasMemory(std::move(memory),&async_wait_result);
  return async_wait_result;
}




