void UntrustedServiceAsyncWaiter::BindObserver(
    ::mojo::PendingRemote<UntrustedServiceObserver> observer, ::ai_chat::mojom::ServiceStatePtr* out_state) {
  base::RunLoop loop;
  proxy_->BindObserver(
      std::move(observer),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::ai_chat::mojom::ServiceStatePtr* out_state
,
             ::ai_chat::mojom::ServiceStatePtr state) {*out_state = std::move(state);
            loop->Quit();
          },
          &loop,
          out_state));
  loop.Run();
}

::ai_chat::mojom::ServiceStatePtr UntrustedServiceAsyncWaiter::BindObserver(
    ::mojo::PendingRemote<UntrustedServiceObserver> observer) {
  ::ai_chat::mojom::ServiceStatePtr async_wait_result;
  BindObserver(std::move(observer),&async_wait_result);
  return async_wait_result;
}

void UntrustedServiceAsyncWaiter::GetPremiumStatus(
    ::ai_chat::mojom::PremiumStatus* out_status, ::ai_chat::mojom::PremiumInfoPtr* out_info) {
  base::RunLoop loop;
  proxy_->GetPremiumStatus(
      base::BindOnce(
          [](base::RunLoop* loop,
             ::ai_chat::mojom::PremiumStatus* out_status
,
             ::ai_chat::mojom::PremiumInfoPtr* out_info
,
             ::ai_chat::mojom::PremiumStatus status,
             ::ai_chat::mojom::PremiumInfoPtr info) {*out_status = std::move(status);*out_info = std::move(info);
            loop->Quit();
          },
          &loop,
          out_status,
          out_info));
  loop.Run();
}






